import openpyxl
wb=openpyxl.load_workbook('/tmp/weo/weoapr2025all.xlsx', read_only=True, data_only=True)
ws=wb.active
rows=[]
for row in ws.iter_rows(min_row=1, max_row=20000, max_col=1, values_only=True):
    v=row[0]
    if v is None:
        continue
    parts=str(v).split('\t')
    rows.append(parts)
header=rows[0]
cols={name:i for i,name in enumerate(header)}
# get Georgia data
result={}
for r in rows[1:]:
    if len(r)<=cols['WEO Subject Code'] or len(r)<=cols['Country']:
        continue
    if r[cols['Country']]=='Georgia' and r[cols['WEO Subject Code']] in ('NGDP_R','NGDP_RPCH'):
        code=r[cols['WEO Subject Code']]
        # build dict of year->value
        data={}
        for year in range(2000,2028):
            idx=cols.get(str(year))
            if idx is not None and idx < len(r):
                val=r[idx]
                data[year]=val if val not in ('','n/a') else None
            else:
                data[year]=None
        result[code]=data
        print(code, 'units', r[cols['Units']], 'scale', r[cols['Scale']])

print('years', list(range(2000,2003)), [result['NGDP_R'][y] for y in range(2000,2003)])
print('growth', [result['NGDP_RPCH'][y] for y in range(2000,2003)])
print('last', [result['NGDP_R'][y] for y in range(2025,2028)])
print('lastg', [result['NGDP_RPCH'][y] for y in range(2025,2028)])
